function slugify(title) {
  return title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

module.exports = { slugify };

import { test } from 'node:test';
import assert from 'node:assert';
import { slugify } from '../src/slug.js';

test('slugify basic example', () => {
  assert.strictEqual(slugify('Hello World!'), 'hello-world');
});

test('slugify already lowercase', () => {
  assert.strictEqual(slugify('hello-world'), 'hello-world');
});

test('slugify multiple spaces', () => {
  assert.strictEqual(slugify('hello   world'), 'hello-world');
});

test('slugify special characters', () => {
  assert.strictEqual(slugify('hello@world#test'), 'hello-world-test');
});

test('slugify leading/trailing spaces', () => {
  assert.strictEqual(slugify('  hello world  '), 'hello-world');
});

test('slugify mixed case', () => {
  assert.strictEqual(slugify('Hello WORLD'), 'hello-world');
});

test('slugify single word', () => {
  assert.strictEqual(slugify('hello'), 'hello');
});

test('slugify with numbers', () => {
  assert.strictEqual(slugify('hello 123 world'), 'hello-123-world');
});

test('slugify empty string', () => {
  assert.strictEqual(slugify(''), '');
});

test('slugify only special characters', () => {
  assert.strictEqual(slugify('!!!'), '');
});

test('slugify dashes and underscores', () => {
  assert.strictEqual(slugify('hello_world-test'), 'hello-world-test');
});

